    {
      "name": "MvPolynomial.support",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → Finset (σ →₀ ℕ)"
    },
    {
      "name": "Polynomial.coeffs",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Semiring R] → Polynomial R → Finset R"
    },
    {
      "name": "MvPolynomial.coeffs",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → Finset R"
    },
    {
      "name": "MvPolynomial.as_sum",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R),\n  p = ∑ v ∈ p.support, (MvPolynomial.monomial v) (MvPolynomial.coeff v p)"
    },
    {
      "name": "FirstOrder.Ring.mvPolynomialSupportLEEquiv",
      "module_name": "Mathlib.RingTheory.MvPolynomial.FreeCommRing",
      "kind": "definition",
      "type": "{ι : Type u_1} →\n  {κ : Type u_2} →\n    {R : Type u_3} →\n      [DecidableEq κ] →\n        [inst : CommRing R] →\n          [DecidableEq R] →\n            (monoms : ι → Finset (κ →₀ ℕ)) → { p // ∀ (i : ι), (p i).support ⊆ monoms i } ≃ ((i : ι) × ↥(monoms i) → R)"
    },
    {
      "name": "MvPolynomial.mem_coeffs_iff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {p : MvPolynomial σ R} {c : R},\n  c ∈ p.coeffs ↔ ∃ n ∈ p.support, c = MvPolynomial.coeff n p"
    }
  ]
}
